import{_ as a,C as s,o as n,c as r,a2 as e,E as i}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"Choose your memory","description":"","frontmatter":{"title":"Choose your memory"},"headers":[],"relativePath":"en/guide/vault.md","filePath":"en/guide/vault.md"}'),h={name:"en/guide/vault.md"};function l(d,t,u,c,g,m){const o=s("Capture");return n(),r("div",null,[t[0]||(t[0]=e('<h1 id="choose-your-memory" tabindex="-1">Choose your memory <a class="header-anchor" href="#choose-your-memory" aria-label="Permalink to &quot;Choose your memory&quot;">​</a></h1><p>Kessho&#39;s memory is a <strong>folder</strong> of Markdown files on your disk. You pick it at first launch and can change it whenever you like. This page explains what you can choose, and what changing it does — and does not do.</p><h2 id="what-the-memory-is" tabindex="-1">What the memory is <a class="header-anchor" href="#what-the-memory-is" aria-label="Permalink to &quot;What the memory is&quot;">​</a></h2><ul><li>An ordinary folder, which you can copy, back up or open with other tools.</li><li>Notes in Markdown, filed by <a href="/en/guide/zones.html">zones</a>.</li><li>Compatible with Obsidian: a folder of Obsidian notes can serve as your memory. Kessho does not depend on it, and does not need Obsidian to be installed.</li></ul><p>Your agents and the application read the <strong>same</strong> folder. The assistants Kessho is declared to are not given any path: the server finds the memory on its own, from the application&#39;s configuration. So changing the memory in the application also changes the one your agents see.</p><h2 id="the-three-ways-to-start" tabindex="-1">The three ways to start <a class="header-anchor" href="#the-three-ways-to-start" aria-label="Permalink to &quot;The three ways to start&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to…</th><th>Pick</th><th>What happens</th></tr></thead><tbody><tr><td>Start from scratch</td><td><strong>New Kessho memory</strong></td><td>Kessho suggests a folder that does not exist yet (&quot;does not exist yet&quot;).</td></tr><tr><td>Use notes you already have</td><td><strong>Existing folder</strong></td><td>Kessho recognises Obsidian folders and counts their notes.</td></tr><tr><td>Pick up a previous installation</td><td><strong>Previous install</strong></td><td>Kessho suggests it when it detects one on your machine.</td></tr></tbody></table><h2 id="choosing-your-memory-at-first-launch" tabindex="-1">Choosing your memory at first launch <a class="header-anchor" href="#choosing-your-memory-at-first-launch" aria-label="Permalink to &quot;Choosing your memory at first launch&quot;">​</a></h2>',8)),i(o,{name:"premier-lancement",alt:"First launch, step 2 of 5: choosing the folder that will hold the memory (existing folder, previous install or a new memory)."}),t[1]||(t[1]=e('<ol><li>At the <strong>Location</strong> step, look at the suggestions. Each shows its kind, its path and its number of notes (&quot;184 notes&quot;).</li><li>Click a suggestion, or type a path in <strong>Memory Path</strong>, or click <strong>Browse…</strong>: the &quot;Choose the memory folder&quot; picker opens.</li><li>If a suggestion says &quot;read-only&quot;, Kessho could not write to it in a test: pick another location instead.</li><li>Click <strong>Next</strong>. At the following step, <strong>Walk the folder</strong> shows you what Kessho reads there, without saving anything.</li><li>On the last screen, check <strong>Memory Location</strong>, then click <strong>Launch Kessho</strong>.</li></ol><p>Each step is detailed in <a href="/en/guide/first-run.html">First launch</a>.</p><h2 id="changing-your-memory-later" tabindex="-1">Changing your memory later <a class="header-anchor" href="#changing-your-memory-later" aria-label="Permalink to &quot;Changing your memory later&quot;">​</a></h2><ol><li>Open <strong>Settings</strong>, then the <strong>Memory</strong> section.</li><li>The <strong>Location</strong> row shows the current folder. Click <strong>Change</strong>.</li><li>Pick a folder in the picker.</li></ol><p>The new path is saved straight away. If you close the picker without choosing, nothing is written. If saving fails, the screen shows &quot;Saving failed.&quot; with the cause, and the old path stays displayed.</p><p><strong>Changing moves no file.</strong> Kessho starts reading the folder you picked; the old folder stays as it is, where it was. To take your notes elsewhere, copy the folder yourself before changing.</p><p>The <strong>Memory</strong> section also shows:</p><ul><li><strong>Content</strong>: the number of notes, the number of files and the size of the folder (for example &quot;184 notes · 190 files · 2.1 MB&quot;);</li><li><strong>Backup</strong>: &quot;None — your files are yours&quot;, &quot;Local git repository, no remote&quot; or &quot;Git repository synced with…&quot; (see <a href="/en/guide/sync.html">Sync</a>);</li><li><strong>Previous installation</strong>, only if a previous installation is detected and not yet migrated.</li></ul><h2 id="if-a-previous-installation-is-detected" tabindex="-1">If a previous installation is detected <a class="header-anchor" href="#if-a-previous-installation-is-detected" aria-label="Permalink to &quot;If a previous installation is detected&quot;">​</a></h2><p>A &quot;Migration available&quot; banner appears above the screens. It offers <strong>Run Migration (1-Click)</strong>, then <strong>Verify Migration</strong>. The migration carries over your profile, the memory location and the connectors of the previous installation.</p><h2 id="what-next" tabindex="-1">What next? <a class="header-anchor" href="#what-next" aria-label="Permalink to &quot;What next?&quot;">​</a></h2><ul><li>See what the memory holds: <a href="/en/guide/home.html">Home</a> and <a href="/en/guide/zones.html">Zones</a>.</li><li>Give the memory to your assistants: <a href="/en/guide/agents.html">Connect your agents</a>.</li></ul>',12))])}const f=a(h,[["render",l]]);export{p as __pageData,f as default};
